examples.template:
MonarchButton({{label}}) { isOpen = true }
    .popover(isPresented: $isOpen, arrowEdge: .top) {
        VStack(alignment: .leading, spacing: theme.spacing.space3) {
            MonarchCopyField("Link", value: {{url}}, size: .sm, isMonospaced: false, copyTitle: "Copy link")
            Divider()
            Link("Email", destination: URL(string: "mailto:?subject=" + {{title}}.replacingOccurrences(of: " ", with: "%20") + "&body=" + {{url}})!)
                .monarchTextStyle(.body)
                .foregroundStyle(theme.colors.textDefault)
        }
        .padding(theme.spacing.space4)
        .frame(width: 330)
        .presentationCompactAdaptation(.popover)
        .presentationBackground(theme.colors.bgRaised)
    }

